package com.snoworca.naruserve.proxy;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import com.snoworca.naruserve.RestApp;
import com.snoworca.naruserve.testing.InMemoryHttpAdapter;
import com.snoworca.naruserve.testing.InMemoryHttpAdapter.ClientRequest;
import com.snoworca.naruserve.testing.InMemoryHttpAdapter.ClientResponse;
import com.snoworca.naruserve.testing.TestApp;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.TimeUnit;
import org.junit.After;
import org.junit.Test;

/**
 * RFC 9112 §6.1: a client that receives an HTTP/1.0 message containing Transfer-Encoding MUST treat the framing as
 * faulty; §6.3 then requires a proxy to answer a response with faulty framing with 502. SEC-PROXY-004 is "stricter
 * than the RFC", so an HTTP/1.0 response with Transfer-Encoding: chunked must be 502 INVALID_RESPONSE, not decoded.
 */
public class ReviewProbe1Test {

    private final InMemoryHttpAdapter adapter = new InMemoryHttpAdapter();
    private final TestApp t = TestApp.create(adapter);
    private final RestApp app = t.app();
    private final List<Throwable> errors = Collections.synchronizedList(new ArrayList<Throwable>());
    private RawBackend backend;

    @After
    public void tearDown() throws IOException {
        app.shutdown(2, TimeUnit.SECONDS);
        if (backend != null) {
            backend.close();
        }
    }

    // SEC-PROXY-004 (RFC 9112 §6.1): Transfer-Encoding on an HTTP/1.0 response is faulty framing -> 502
    @Test(timeout = 30000)
    public void sec_PROXY_004_transferEncodingOnHttp10ResponseIsInvalidResponse() throws IOException {
        backend = RawBackend.answering(
                "HTTP/1.0 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n5\r\nhello\r\n0\r\n\r\n");
        app.use("/api", Proxy.to(backend.url()));
        app.onError((error, req, res) -> errors.add(error));
        t.start();

        ClientResponse r = adapter.send(ClientRequest.of("GET", "/api/x"));

        assertEquals("status (body: " + r.text() + ")", 502, r.status());
        synchronized (errors) {
            assertEquals("errors: " + errors, 1, errors.size());
            assertTrue(errors.get(0) instanceof ProxyException);
            assertSame(ProxyException.Kind.INVALID_RESPONSE, ((ProxyException) errors.get(0)).kind());
        }
    }
}
